+export const circuitRequest = Symbol("ofetch.circuitRequest");
+
+export function createCircuitBreakerState(): CircuitBreakerState {
+  return { circuits: new Map() };
+}
+
+export function resolveCircuitBreaker(
+  option: FetchOptions["circuitBreaker"]
+): ResolvedCircuitBreakerOptions | undefined {
+  if (!option) {
+    return;
+  }
+  if (option === true) {
+    return {
+      threshold: 5,
+      cooldown: 30_000,
+      halfOpenMaxRequests: 1,
+      failureStatusCodes: defaultFailureStatusCodes,
+    };
+  }
+  return {
+    threshold: option.threshold,
+    cooldown: option.cooldown,
+    halfOpenMaxRequests: option.halfOpenMaxRequests ?? 1,
+    failureStatusCodes: option.failureStatusCodes ?? defaultFailureStatusCodes,
+  };
+}
+
+export function getRequestOrigin(request: FetchRequest): string | undefined {
+  const url = request instanceof Request ? request.url : String(request);
+  try {
+    return new URL(url).origin;
+  } catch {
+    // Relative requests have no origin until a baseURL (or browser location)
+    // has resolved them. The former is handled before this function is called.
+    return;
+  }
+}
+
+export function acquireCircuit(
+  state: CircuitBreakerState,
+  request: CircuitRequest,
+  origin: string
+): boolean {
+  request.origin = origin;
+  const entry = state.circuits.get(origin) || {
+    failures: 0,
+    state: "closed" as const,
+    openedAt: 0,
+    halfOpenRequests: 0,
+  };
+  state.circuits.set(origin, entry);
+
+  const now = Date.now();
+  if (entry.state === "open") {
+    if (now - entry.openedAt < request.config.cooldown) {
+      request.blocked = true;
+      return false;
+    }
+    entry.state = "half-open";
+    entry.halfOpenRequests = 0;
+  }
+  if (entry.state === "half-open") {
+    if (entry.halfOpenRequests >= request.config.halfOpenMaxRequests) {
+      request.blocked = true;
+      return false;
+    }
+    entry.halfOpenRequests++;
+  }
+  request.acquired = true;
+  return true;
+}
+
+export function settleCircuit(
+  state: CircuitBreakerState,
+  request: CircuitRequest,
+  outcome: "success" | "failure" | "neutral"
+) {
+  if (!request.acquired || !request.origin) {
+    return;
+  }
+  const entry = state.circuits.get(request.origin);
+  if (!entry) {
+    return;
+  }
+  if (entry.state === "half-open") {
+    entry.halfOpenRequests--;
+  }
+  if (outcome === "success") {
+    entry.failures = 0;
+    if (entry.state === "half-open") {
+      entry.state = "closed";
+      entry.halfOpenRequests = 0;
+    }
+    return;
+  }
+  if (outcome === "failure") {
+    if (entry.state === "half-open") {
+      entry.state = "open";
+      entry.openedAt = Date.now();
+      entry.halfOpenRequests = 0;
+      return;
+    }
+    entry.failures++;
+    if (entry.failures >= request.config.threshold) {
+      entry.state = "open";
+      entry.openedAt = Date.now();
+    }
+  }
